const input = $input.first().json;
const headers = input.headers ?? {};
const provided = headers['x-sattva-webhook-hmac'] ?? headers['X-Sattva-Webhook-Hmac'];
const expected = $env.N8N_WEBHOOK_HMAC;
if (typeof expected !== 'string' || !expected || typeof provided !== 'string' || provided !== expected) {
  throw new Error('invalid x-sattva-webhook-hmac');
}
const payload = input.body ?? input;
if (payload == null || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('payload required');
const forbidden = new Set(['bytes','pdf','path','nextcloud_folder_path','file_bytes','sfc_licence_number','cbsa_bond_number','insurance_policy_no']);
for (const key of Object.keys(payload)) {
  if (forbidden.has(key)) throw new Error('RED key forbidden in sale hold: ' + key);
}
if (payload.order_id == null) throw new Error('order_id required');
if (typeof payload.reason !== 'string' || !payload.reason) throw new Error('reason required');
return [{ json: { order_id: Number(payload.order_id), reason: payload.reason.slice(0, 255) } }];
